import React from 'react';
import './AddMovieForm.css'; // Import the CSS file

const AddMovieForm = ({ newMovie, inputChangeHandler, addMovieHandler }) => {
  return (
    <div className="add-movie-form">
     

      <label htmlFor="title">Movie Title</label>
      <input
        id="title"
        type="text"
        name="title"
        value={newMovie.title}
        onChange={inputChangeHandler}
        placeholder="Movie Title"
        className="form-input"
      />

      <label htmlFor="openingText">Opening Text</label>
      <textarea
        id="openingText"
        name="openingText"
        value={newMovie.openingText}
        onChange={inputChangeHandler}
        placeholder="Opening Text"
        className="form-input"
      />

      <label htmlFor="releaseDate">Release Date</label>
      <input
        id="releaseDate"
        type="date"
        name="releaseDate"
        value={newMovie.releaseDate}
        onChange={inputChangeHandler}
        className="form-input"
      />

      <button className="form-button" onClick={addMovieHandler}>Add Movie</button>
    </div>
  );
};

export default AddMovieForm;
